import{_ as a,q as t,z as e,V as s}from"./chunks/framework.OtifAeFI.js";const o=JSON.parse('{"title":"AI很聪明，但也不是神","description":"不要把AI当初仅有的外置大脑","frontmatter":{"title":"AI很聪明，但也不是神","tags":["AI"],"categories":["杂谈"],"date":"2025-03-22T00:00:00.000Z","description":"不要把AI当初仅有的外置大脑","articleGPT":"AI技术虽极大提升了生产效率，但其本质仍是基于统计概率的预测引擎。本文以Deepseek为例，剖析大语言模型普遍存在的AI幻觉现象：从Transformer架构原理、训练数据局限、上下文窗口限制等角度，揭示模型产生虚构内容的技术根源。通过对比主流模型14.3%的幻觉率数据和实际编程案例，强调保持批判性思维的重要性，并提供优化提问、分批输出、交叉验证、RAG技术等四类实用方法，帮助用户在享受AI便利的同时规避认知风险。","references":[{"title":"DeepSeek与AI幻觉","url":"https://2s.lol/sC2Rye"},{"title":"When Machines Dream： A Dive in AI Hallucinations [Study]","url":"https://www.tidio.com/blog/ai-hallucinations/"},{"title":"AI 有多会一本正经地瞎编？超出你的想象！深度解析大模型的\\"幻觉\\"机制 | 科普中国","url":"https://zhuanlan.zhihu.com/p/24896510660"},{"title":"Hallucination Leaderboard","url":"https://github.com/vectara/hallucination-leaderboard"}],"head":[["link",{"rel":"canonical","href":"https://www.696898.xyz/posts/2025/0322"}]]},"headers":[],"relativePath":"posts/2025/0322.md","filePath":"posts/2025/0322.md","lastUpdated":1742650623000}');const i=a({name:"posts/2025/0322.md"},[["render",function(a,o,i,r,n,p){return e(),t("div",null,o[0]||(o[0]=[s("",41)]))}]]);export{o as __pageData,i as default};
